llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Zeaxanthin, a highly lipophilic polyene with terminal cyclohexenyl rings, shows high bioavailability only when ingested in a fat-rich matrix such as egg yolk; this context-dependent absorption is the closest structural analogy to the lipophilic retinoid query and does not support high absolute oral bioavailability under ordinary conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Desvenlafaxine, a small polar phenol-containing drug, has high absolute oral bioavailability (~80%), but its small hydrophilic structure is not transferable to the large, poorly soluble retinoid amide query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Teriflunomide, a small lipophilic amide with near-complete oral bioavailability, shares only an amide-phenyl motif with the query and lacks the long conjugated polyene and high lipophilicity that limit fenretinide absorption.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fenretinide, a synthetic retinoid with recognized poor and variable oral bioavailability due to low aqueous solubility and first-pass metabolism. The visible high-F records are structurally distant or context-dependent, so the F >= 20% threshold is better supported as low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide is provided in the visible records.",
    "No quantitative low-F retinoid comparator is available; the closest analog (zeaxanthin) is reported only qualitatively and in a fat-rich food matrix.",
    "The effect of formulation or food co-administration on fenretinide absorption is not addressed by the visible evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

